styleTag:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
}

#wheelWidget {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  box-sizing: border-box;
}

#scaleStage {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 900px;
  height: 900px;
  transform-origin: 50% 50%;
  transform: translate(-50%, -50%) scale(1);
  will-change: transform;
}

.timer-panel {
  position: absolute;
  z-index: 8;
  top: 18px;
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  min-width: 250px;
  padding: 10px 22px 11px;
  border-radius: 18px;
  text-align: center;
  color: #ffffff;
  background: rgba(10, 10, 18, 0.82);
  border: 2px solid rgba(255, 255, 255, .2);
  box-shadow:
    0 10px 32px rgba(0, 0, 0, .4),
    inset 0 0 18px rgba(255, 255, 255, .05);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.timer-panel.inactive {
  opacity: .72;
}

#timerLabel {
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 2px;
  opacity: .86;
}

#timerValue {
  margin-top: 1px;
  font-size: 34px;
  line-height: 1;
  font-weight: 1000;
  letter-spacing: 2px;
  text-shadow: 0 2px 6px rgba(0, 0, 0, .9);
}

#entryCount {
  margin-top: 4px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 1.5px;
  opacity: .8;
}

.wheel-stage {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 760px;
  height: 760px;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  justify-content: center;
  filter: drop-shadow(0 18px 26px rgba(0, 0, 0, .45));
}

#wheelCanvas {
  width: 760px;
  height: 760px;
  transform-origin: 50% 50%;
  will-change: transform;
}

.wheel-hub {
  position: absolute;
  z-index: 5;
  width: 84px;
  height: 84px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 35% 30%, #ffffff 0 7%, #e7e7ed 9% 20%, #252535 25% 55%, #08080d 72%);
  border: 5px solid rgba(255, 255, 255, .9);
  box-shadow:
    0 4px 14px rgba(0, 0, 0, .65),
    inset 0 0 12px rgba(255, 255, 255, .3);
}

.pointer {
  position: absolute;
  z-index: 10;
  right: -42px;
  top: 50%;
  width: 72px;
  height: 76px;
  transform: translateY(-50%);
  pointer-events: none;
}

.pointer-tip {
  position: absolute;
  left: 0;
  top: 4px;
  width: 0;
  height: 0;
  border-top: 34px solid transparent;
  border-bottom: 34px solid transparent;
  border-right: 62px solid #fff200;
  filter:
    drop-shadow(-2px 0 0 #ffffff) drop-shadow(0 0 8px #fff200) drop-shadow(0 0 18px #ff7a00) drop-shadow(0 0 30px rgba(255, 70, 0, .85));
}

.empty-state {
  position: absolute;
  z-index: 7;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: rgba(255, 255, 255, .9);
  font-size: 20px;
  font-weight: 900;
  letter-spacing: 2px;
  text-align: center;
  text-shadow: 0 3px 8px rgba(0, 0, 0, 1);
  pointer-events: none;
}

.result-overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.result-overlay.hidden {
  display: none;
}

.result-card {
  width: min(690px, 82%);
  box-sizing: border-box;
  padding: 30px 36px 34px;
  border-radius: 28px;
  text-align: center;
  color: #ffffff;
  background:
    linear-gradient(145deg, rgba(22, 22, 35, .96), rgba(8, 8, 15, .96));
  border: 3px solid rgba(255, 255, 255, .92);
  box-shadow:
    0 18px 55px rgba(0, 0, 0, .65),
    0 0 45px rgba(255, 255, 255, .12);
  animation: resultIn .5s cubic-bezier(.18, .9, .25, 1.2) both;
}

.result-header {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: 3px;
  text-transform: uppercase;
  opacity: .8;
  text-shadow: 0 2px 5px rgba(0, 0, 0, .9);
}

.result-winner {
  margin-top: 10px;
  font-size: clamp(34px, 7vw, 72px);
  line-height: 1.05;
  font-weight: 1000;
  overflow-wrap: anywhere;
  text-shadow:
    0 4px 0 rgba(0, 0, 0, .55),
    0 0 15px rgba(255, 255, 255, .22);
}

#confettiCanvas {
  position: absolute;
  z-index: 40;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

@keyframes resultIn {
  0% {
    transform: scale(.72) translateY(28px);
    opacity: 0;
  }

  70% {
    transform: scale(1.04) translateY(-4px);
    opacity: 1;
  }

  100% {
    transform: scale(1) translateY(0);
    opacity: 1;
  }
}

.streamerbot-status {
  max-height: 0;
  margin-top: 0;
  overflow: hidden;
  font-size: 9px;
  line-height: 1;
  font-weight: 900;
  letter-spacing: 1.2px;
  opacity: 0;
  text-transform: uppercase;
  transition:
    opacity .2s ease,
    max-height .2s ease,
    margin-top .2s ease;
}

.streamerbot-status.visible {
  max-height: 12px;
  margin-top: 4px;
  opacity: .9;
}

.streamerbot-status.visible.connected,
.streamerbot-status.visible.offline {
  opacity: 1;
}

scriptTag:
const scaleStage = document.getElementById("scaleStage");
const canvas = document.getElementById("wheelCanvas");
const ctx = canvas.getContext("2d");
const resultOverlay = document.getElementById("resultOverlay");
const resultHeaderEl = document.getElementById("resultHeader");
const resultWinnerEl = document.getElementById("resultWinner");
const timerPanel = document.getElementById("timerPanel");
const timerValueEl = document.getElementById("timerValue");
const timerLabelEl = document.getElementById("timerLabel");
const entryCountEl = document.getElementById("entryCount");
const streamerBotStatusEl = document.getElementById("streamerBotStatus");
const emptyState = document.getElementById("emptyState");
const confettiCanvas = document.getElementById("confettiCanvas");
const confettiCtx = confettiCanvas.getContext("2d");

const DEBUG = true;
const TAU = Math.PI * 2;
const MAX_SLICE_CHARS = 15;
const DESIGN_WIDTH = 900;
const DESIGN_HEIGHT = 900;

let widgetScaleMultiplier = parseFloat("{widget_scale}") || 1;
let resizeObserver = null;

let manualMode = parseToggle("{manual_mode}");
let manualHeaderText = "{manual_header_text}";

let autoSpinFromSubs = parseToggle("{auto_spin_from_subs}");
let communitySubsPerSpin = Math.max(
  1,
  parseInt("{community_subs_per_spin}", 10) || 5
);

let manualGiftBombOnly = parseToggle(
  "{manual_gift_bomb_only}"
);
let manualGiftBombRequired = Math.max(
  1,
  parseInt("{manual_gift_bomb_required}", 10) || 10
);

let subGiftBombOnly = parseToggle(
  "{sub_gift_bomb_only}"
);
let subGiftBombRequired = Math.max(
  1,
  parseInt("{sub_gift_bomb_required}", 10) || 10
);

let collectionMinutes = parseFloat("{collection_time_minutes}") || 10;
let maxEntriesPerPerson =
  Math.max(0, parseInt("{max_entries_per_person}", 10) || 0);
let autoStopAtEnd = parseToggle("{auto_stop_at_timer_end}");
let autoSpinAtEnd = parseToggle("{auto_spin_at_timer_end}");
let removeWinnerAfterSpin = parseToggle("{remove_winner_after_spin}");
let removeSubWinnerAfterSpin = parseToggle(
  "{remove_sub_winner_after_spin}"
);
let confettiEnabled = parseToggle("{confetti_enabled}");
let resultHeader = "{result_header}";
let resultDisplaySeconds = parseFloat("{result_display_duration}") || 8;
let resultSoundUrl = "{result_sound_url}";
let resultSoundVolume = parseFloat("{result_sound_volume}");
let spinDurationSeconds = parseFloat("{spin_duration_seconds}") || 8;
let minimumRotations = parseInt("{minimum_full_rotations}", 10) || 7;
let idleSpinEnabled = parseToggle("{idle_spin_enabled}");
let idleSpinRotationsPerMinute =
  parseFloat("{idle_spin_rotations_per_minute}") || 0.35;

let useRemoteConnection = parseToggle("{use_remote_connection}");

let localWebSocketUrl =
  String("{local_websocket_url}" || "").trim() ||
  "ws://127.0.0.1:8080/";

let remoteWebSocketUrl =
  String("{remote_websocket_url}" || "").trim();

let streamerBotPassword =
  String("{streamerbot_password}" || "");

let streamerBotSocket = null;
let streamerBotReconnectTimer = 0;
let streamerBotStatusHideTimer = 0;
let streamerBotAuthenticated = false;
let streamerBotSubscribed = false;

let palette = [
  "{color_1}",
  "{color_2}",
  "{color_3}",
  "{color_4}",
  "{color_5}"
].filter(isUsableColor);

let manualEntries = [
  "{manual_entry_1}",
  "{manual_entry_2}",
  "{manual_entry_3}",
  "{manual_entry_4}",
  "{manual_entry_5}",
  "{manual_entry_6}",
  "{manual_entry_7}",
  "{manual_entry_8}",
  "{manual_entry_9}",
  "{manual_entry_10}",
  "{manual_entry_11}",
  "{manual_entry_12}",
  "{manual_entry_13}",
  "{manual_entry_14}",
  "{manual_entry_15}"
];

let subscriberEntries = [];
let subscriberEntryCounts = new Map();

let collecting = false;
let collectionEndsAt = 0;
let collectionTick = 0;
let rotation = 0;
let spinning = false;
let activeSpinFrame = 0;
let spinGeneration = 0;
let resultTimer = 0;
let confettiFrame = 0;
let confettiPieces = [];
let idleSpinFrame = 0;
let idleSpinLastTime = 0;

let communitySubProgress = 0;
let pendingCommunitySpins = 0;
let communitySpinTimer = 0;
let communityGoalFlashTimer = 0;
let communityGoalFlashing = false;

/*
 * Manual auto-spin uses Streamer.bot Custom Events as the source of truth.
 * A normal sub event is delayed briefly so a paired Gift Bomb event can
 * replace it with the bomb's exact quantity instead of counting +1 as well.
 */
const pendingManualSubTimers = new Map();
const recentGiftBombs = new Map();

/*
 * Tracks the normal wheel:addSubscriber:<name> event that is paired with
 * wheel:addGiftBomb:<count>:<name>. This lets subscriber mode add the
 * exact bomb quantity without turning a 5-bomb into 6 entries.
 */
const recentSubscriberNameEvents = new Map();

const MANUAL_SUB_DELAY_MS = 900;
const GIFT_BOMB_DEDUPE_MS = 2500;

function applyWidgetScale() {
  if (!scaleStage) return;

  const viewportWidth = Math.max(
    1,
    document.documentElement.clientWidth || window.innerWidth
  );
  const viewportHeight = Math.max(
    1,
    document.documentElement.clientHeight || window.innerHeight
  );

  const fitScale = Math.min(
    viewportWidth / DESIGN_WIDTH,
    viewportHeight / DESIGN_HEIGHT
  );

  const manualScale = Number.isFinite(widgetScaleMultiplier)
    ? Math.max(0.05, widgetScaleMultiplier)
    : 1;

  const finalScale = fitScale * manualScale;

  scaleStage.style.transform =
    `translate(-50%, -50%) scale(${finalScale})`;
}

function startWidgetAutoScale() {
  applyWidgetScale();
  window.addEventListener("resize", applyWidgetScale);

  if (typeof ResizeObserver !== "undefined") {
    resizeObserver = new ResizeObserver(applyWidgetScale);
    resizeObserver.observe(document.documentElement);
    resizeObserver.observe(document.body);
  }
}

function debug(...args) {
  if (DEBUG) console.log("[POGLY WHEEL]", ...args);
}

function parseToggle(value) {
  if (value === true) return true;
  const normalized = String(value ?? "").trim().toLowerCase();
  return !["false", "0", "off", "no", "disabled", ""].includes(normalized);
}

function isUsableColor(value) {
  const color = String(value || "").trim();
  return color && color.toLowerCase() !== "transparent";
}

function normalizeVolume(value) {
  let number = Number(value);
  if (!Number.isFinite(number)) number = 1;
  if (number > 1) number /= 100;
  return Math.max(0, Math.min(1, number));
}

function currentEntries() {
  const source = manualMode ? manualEntries : subscriberEntries;

  return source
    .map(value => String(value || "").trim())
    .filter(Boolean);
}

function sliceText(value) {
  const text = String(value || "");

  return text.length > MAX_SLICE_CHARS
    ? text.slice(0, MAX_SLICE_CHARS) + "..."
    : text;
}

function manualSliceLines(value) {
  const text = String(value || "")
    .replace(/\s+/g, " ")
    .trim();

  if (!text) return [""];

  const maxLineCharacters = 16;
  const maxTotalCharacters = maxLineCharacters * 2;
  const shortened =
    text.length > maxTotalCharacters
      ? text.slice(0, maxTotalCharacters - 3).trimEnd() + "..."
      : text;

  const words = shortened.split(" ");
  const lines = [""];

  words.forEach(word => {
    const currentLine = lines[lines.length - 1];
    const candidate = currentLine
      ? currentLine + " " + word
      : word;

    if (
      candidate.length <= maxLineCharacters ||
      lines.length === 2
    ) {
      lines[lines.length - 1] = candidate;
    } else {
      lines.push(word);
    }
  });

  if (lines.length > 2) {
    const overflow = lines.slice(1).join(" ");
    lines.length = 1;
    lines.push(
      overflow.length > maxLineCharacters
        ? overflow.slice(0, maxLineCharacters - 3).trimEnd() + "..."
        : overflow
    );
  }

  if (lines[1] && lines[1].length > maxLineCharacters) {
    lines[1] =
      lines[1].slice(0, maxLineCharacters - 3).trimEnd() + "...";
  }

  return lines.slice(0, 2);
}

function paletteColor(index, count) {
  const colors = palette.length
    ? palette
    : ["#ff2d95", "#6a38ff", "#00b8ff", "#00d98b", "#ff8a00"];

  if (colors.length === 1) return colors[0];

  /*
   * The normal modulo sequence already prevents matching neighbors
   * when at least two distinct colors exist. The final slice is
   * corrected when its color would match the first slice.
   */
  let colorIndex = index % colors.length;

  if (
    count > 1 &&
    index === count - 1 &&
    colorIndex === 0
  ) {
    colorIndex = 1 % colors.length;
  }

  return colors[colorIndex];
}

function drawWheel() {
  const entries = currentEntries();
  const width = canvas.width;
  const height = canvas.height;
  const cx = width / 2;
  const cy = height / 2;
  const radius = Math.min(cx, cy) - 16;

  ctx.clearRect(0, 0, width, height);
  emptyState.style.display = entries.length ? "none" : "block";

  if (!entries.length) {
    drawEmptyWheel(cx, cy, radius);
    updateEntryCount();
    return;
  }

  const sliceAngle = TAU / entries.length;
  const fontSize = Math.max(
    9,
    Math.min(27, 31 - Math.log2(Math.max(entries.length, 2)) * 3.2)
  );

  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(rotation);

  entries.forEach((entry, index) => {
    const start = index * sliceAngle - sliceAngle / 2;
    const end = start + sliceAngle;

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.arc(0, 0, radius, start, end);
    ctx.closePath();
    ctx.fillStyle = paletteColor(index, entries.length);
    ctx.fill();

    ctx.lineWidth = entries.length > 120 ? 0.6 : 2;
    ctx.strokeStyle = "rgba(255,255,255,.48)";
    ctx.stroke();

    if (entries.length <= 350) {
      const center = start + sliceAngle / 2;
      const worldAngle = center + rotation;

      ctx.save();
      ctx.rotate(center);
      ctx.translate(radius * 0.62, 0);

      /*
       * Use the slice's final screen angle, including wheel rotation,
       * so labels remain upright both during and after every spin.
       */
      const upsideDown = Math.cos(worldAngle) < 0;
      if (upsideDown) ctx.rotate(Math.PI);

      const textFontSize =
        manualMode
          ? Math.max(9, fontSize - 1)
          : fontSize;

      ctx.font = `900 ${textFontSize}px Arial, sans-serif`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.lineJoin = "round";
      ctx.miterLimit = 2;

      const maxWidth = Math.max(42, radius * 0.62);
      const lines =
        manualMode
          ? manualSliceLines(entry)
          : [sliceText(entry)];

      const lineHeight = textFontSize * 1.05;
      const firstLineY =
        lines.length === 2
          ? -lineHeight / 2
          : 0;

      ctx.lineWidth = Math.max(2.5, textFontSize * .2);
      ctx.strokeStyle = "rgba(0,0,0,.88)";
      ctx.fillStyle = "#ffffff";

      lines.forEach((line, lineIndex) => {
        const y = firstLineY + lineIndex * lineHeight;

        ctx.strokeText(line, 0, y, maxWidth);
        ctx.fillText(line, 0, y, maxWidth);
      });

      ctx.restore();
    }
  });

  ctx.restore();

  ctx.beginPath();
  ctx.arc(cx, cy, radius, 0, TAU);
  ctx.lineWidth = 10;
  ctx.strokeStyle = "rgba(255,255,255,.96)";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, cy, radius - 7, 0, TAU);
  ctx.lineWidth = 3;
  ctx.strokeStyle = "rgba(0,0,0,.5)";
  ctx.stroke();

  updateEntryCount();
}

function drawEmptyWheel(cx, cy, radius) {
  const colors = palette.length
    ? palette
    : ["#ff2d95", "#6a38ff", "#00b8ff", "#00d98b", "#ff8a00"];

  const count = 12;
  const slice = TAU / count;

  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(rotation);

  for (let index = 0; index < count; index++) {
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.arc(
      0,
      0,
      radius,
      index * slice,
      (index + 1) * slice
    );
    ctx.closePath();
    ctx.fillStyle = colors[index % colors.length];
    ctx.globalAlpha = 1;
    ctx.fill();
  }

  ctx.restore();

  ctx.globalAlpha = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, radius, 0, TAU);
  ctx.lineWidth = 10;
  ctx.strokeStyle = "rgba(255,255,255,.75)";
  ctx.stroke();
}

function updateEntryCount() {
  const count = currentEntries().length;

  if (manualMode && autoSpinFromSubs) {
    if (manualGiftBombOnly) {
      entryCountEl.textContent = communityGoalFlashing
        ? "SPINNING..."
        : `GIFT ${manualGiftBombRequired} AT ONCE TO SPIN!`;
    } else {
      entryCountEl.textContent = communityGoalFlashing
        ? "SPINNING..."
        : "REACH THE GOAL TO SPIN THE WHEEL!";
    }
    return;
  }

  if (manualMode) {
    entryCountEl.textContent =
      `${count} ${count === 1 ? "ENTRY" : "ENTRIES"}`;
    return;
  }

  const people = subscriberEntryCounts.size;

  if (subGiftBombOnly) {
    const capText =
      maxEntriesPerPerson > 0
        ? `${maxEntriesPerPerson} ENTRIES MAX`
        : "UNLIMITED ENTRIES";

    entryCountEl.textContent =
      `${count} ${count === 1 ? "ENTRY" : "ENTRIES"} • ` +
      `${people} ${people === 1 ? "PERSON" : "PEOPLE"} • ` +
      capText;
    return;
  }

  const capText =
    maxEntriesPerPerson > 0
      ? `MAX ${maxEntriesPerPerson} EACH`
      : "UNLIMITED EACH";

  entryCountEl.textContent =
    `${count} ${count === 1 ? "ENTRY" : "ENTRIES"} • ` +
    `${people} ${people === 1 ? "PERSON" : "PEOPLE"} • ` +
    capText;
}

function formatTime(milliseconds) {
  const totalSeconds = Math.max(0, Math.ceil(milliseconds / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;

  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}


function normalizeEventUser(value) {
  return String(value || "")
    .trim()
    .toLowerCase();
}

function clearPendingManualSub(userName) {
  const key = normalizeEventUser(userName);
  const timer = pendingManualSubTimers.get(key);

  if (timer) {
    clearTimeout(timer);
    pendingManualSubTimers.delete(key);
    return true;
  }

  return false;
}

function queueManualSingleSub(userName, source = "custom-single-sub") {
  if (!manualMode || !autoSpinFromSubs) return false;
  if (manualGiftBombOnly) return false;

  const displayName = String(userName || "Subscriber").trim() || "Subscriber";
  const key = normalizeEventUser(displayName);

  const recentBombAt = recentGiftBombs.get(key) || 0;
  if (Date.now() - recentBombAt <= GIFT_BOMB_DEDUPE_MS) {
    debug("Ignored paired +1 event after gift bomb", {
      displayName,
      source
    });
    return true;
  }

  clearPendingManualSub(displayName);

  const timer = setTimeout(() => {
    pendingManualSubTimers.delete(key);

    addCommunitySubUnits(
      1,
      source
    );
  }, MANUAL_SUB_DELAY_MS);

  pendingManualSubTimers.set(key, timer);

  debug("Queued manual +1 sub", {
    displayName,
    source,
    delayMs: MANUAL_SUB_DELAY_MS
  });

  return true;
}

function registerManualGiftBomb(units, userName) {
  if (!manualMode || !autoSpinFromSubs) return false;

  const safeUnits = Math.max(
    1,
    Math.floor(Number(units) || 1)
  );

  if (manualGiftBombOnly) {
    const earnedSpins = Math.floor(
      safeUnits / manualGiftBombRequired
    );

    if (earnedSpins <= 0) {
      debug("Gift bomb below manual requirement", {
        safeUnits,
        manualGiftBombRequired
      });
      return false;
    }

    pendingCommunitySpins += earnedSpins;
    showCommunityGoalReached();

    debug("Manual gift-bomb-only spins earned", {
      safeUnits,
      manualGiftBombRequired,
      earnedSpins,
      pendingCommunitySpins
    });

    return true;
  }

  const displayName = String(userName || "Gift Gifter").trim() || "Gift Gifter";
  const key = normalizeEventUser(displayName);
  const dedupeKey = `${key}:${safeUnits}`;
  const now = Date.now();
  const lastBombAt = recentGiftBombs.get(dedupeKey) || 0;

  if (now - lastBombAt <= GIFT_BOMB_DEDUPE_MS) {
    debug("Ignored duplicate gift bomb event", {
      displayName,
      safeUnits
    });
    return true;
  }

  clearPendingManualSub(displayName);

  recentGiftBombs.set(key, now);
  recentGiftBombs.set(dedupeKey, now);

  setTimeout(() => {
    if (recentGiftBombs.get(key) === now) {
      recentGiftBombs.delete(key);
    }

    if (recentGiftBombs.get(dedupeKey) === now) {
      recentGiftBombs.delete(dedupeKey);
    }
  }, GIFT_BOMB_DEDUPE_MS + 250);

  return addCommunitySubUnits(
    safeUnits,
    "streamerbot-gift-bomb"
  );
}

function clearCommunitySpinTimer() {
  if (communitySpinTimer) {
    clearTimeout(communitySpinTimer);
    communitySpinTimer = 0;
  }
}

function clearCommunityGoalFlash() {
  if (communityGoalFlashTimer) {
    clearTimeout(communityGoalFlashTimer);
    communityGoalFlashTimer = 0;
  }

  communityGoalFlashing = false;
}

function updateManualSubProgressDisplay() {
  if (!manualMode || !autoSpinFromSubs) return;

  if (manualGiftBombOnly) {
    timerLabelEl.textContent = "GIFT WHEEL";
    timerValueEl.textContent =
      `${manualGiftBombRequired} GIFTED`;
  } else {
    timerLabelEl.textContent = "COMMUNITY SUBS";
    timerValueEl.textContent = communityGoalFlashing
      ? `${communitySubsPerSpin} / ${communitySubsPerSpin}`
      : `${communitySubProgress} / ${communitySubsPerSpin}`;
  }

  timerPanel.classList.remove("inactive");
  updateEntryCount();
}

function showCommunityGoalReached() {
  clearCommunityGoalFlash();
  communityGoalFlashing = true;
  updateManualSubProgressDisplay();

  communityGoalFlashTimer = setTimeout(() => {
    communityGoalFlashTimer = 0;
    communityGoalFlashing = false;
    updateManualSubProgressDisplay();
    processCommunitySpinQueue();
  }, 600);
}

function processCommunitySpinQueue() {
  clearCommunitySpinTimer();

  if (
    !manualMode ||
    !autoSpinFromSubs ||
    pendingCommunitySpins <= 0 ||
    spinning ||
    currentEntries().length === 0 ||
    !resultOverlay.classList.contains("hidden")
  ) {
    return;
  }

  pendingCommunitySpins -= 1;

  debug("Starting queued community sub spin", {
    pendingCommunitySpins,
    communitySubProgress,
    communitySubsPerSpin
  });

  spinWheel();
}

function addCommunitySubUnits(units, source = "unknown") {
  if (!manualMode || !autoSpinFromSubs) return false;

  const safeUnits = Math.max(
    0,
    Math.floor(Number(units) || 0)
  );

  if (!safeUnits) return false;

  const previousProgress = communitySubProgress;
  const combined = previousProgress + safeUnits;
  const earnedSpins = Math.floor(
    combined / communitySubsPerSpin
  );

  communitySubProgress =
    combined % communitySubsPerSpin;

  if (earnedSpins > 0) {
    pendingCommunitySpins += earnedSpins;
  }

  if (earnedSpins > 0) {
    showCommunityGoalReached();
  } else {
    updateManualSubProgressDisplay();
  }

  debug("Community subs added", {
    source,
    units: safeUnits,
    previousProgress,
    communitySubProgress,
    communitySubsPerSpin,
    earnedSpins,
    pendingCommunitySpins
  });

  return true;
}

function updateTimerDisplay() {
  if (manualMode) {
    if (autoSpinFromSubs) {
      updateManualSubProgressDisplay();
    } else {
      timerLabelEl.textContent =
        manualHeaderText || "MANUAL WHEEL";
      timerValueEl.textContent = "READY";
      timerPanel.classList.add("inactive");
    }

    return;
  }

  if (!collecting) {
    timerLabelEl.textContent = subGiftBombOnly
      ? `${subGiftBombRequired} GIFTED = 1 ENTRY`
      : "SUB COLLECTION";
    timerValueEl.textContent = "STOPPED";
    timerPanel.classList.add("inactive");
    updateEntryCount();
    return;
  }

  timerPanel.classList.remove("inactive");
  timerLabelEl.textContent = subGiftBombOnly
    ? `${subGiftBombRequired} GIFTED = 1 ENTRY`
    : "SUBS ARE BEING ENTERED";
  timerValueEl.textContent = formatTime(collectionEndsAt - Date.now());

  if (Date.now() >= collectionEndsAt) {
    if (autoStopAtEnd) {
      finishCollection();
    } else {
      timerValueEl.textContent = "00:00";
      timerLabelEl.textContent = subGiftBombOnly
        ? `${subGiftBombRequired} GIFTED = 1 ENTRY`
        : "SUB COLLECTION OVERTIME";
    }
  }
}

function startCollection() {
  if (manualMode || spinning) return;

  stopCollection(false);

  const safeMinutes =
    Number.isFinite(collectionMinutes) && collectionMinutes > 0
      ? collectionMinutes
      : 10;

  collecting = true;
  collectionEndsAt = Date.now() + safeMinutes * 60 * 1000;
  collectionTick = setInterval(updateTimerDisplay, 200);
  updateTimerDisplay();

  debug("Collection started", {
    minutes: safeMinutes,
    endsAt: new Date(collectionEndsAt).toISOString()
  });
}

function finishCollection() {
  if (!collecting) return;

  collecting = false;
  if (collectionTick) clearInterval(collectionTick);
  collectionTick = 0;

  timerLabelEl.textContent = subGiftBombOnly
    ? `${subGiftBombRequired} GIFTED = 1 ENTRY`
    : "SUB COLLECTION";
  timerValueEl.textContent = "COMPLETE";
  timerPanel.classList.add("inactive");

  debug("Collection timer completed", {
    entries: subscriberEntries.slice()
  });

  if (autoSpinAtEnd && subscriberEntries.length) {
    setTimeout(spinWheel, 500);
  }
}

function stopCollection(showStopped = true) {
  collecting = false;

  if (collectionTick) clearInterval(collectionTick);
  collectionTick = 0;

  if (showStopped) {
    timerLabelEl.textContent = subGiftBombOnly
      ? `${subGiftBombRequired} GIFTED = 1 ENTRY`
      : "SUB COLLECTION";
    timerValueEl.textContent = "STOPPED";
    timerPanel.classList.add("inactive");
  }
}

function clearSubscribers() {
  if (spinning) return;

  subscriberEntries = [];
  subscriberEntryCounts.clear();
  drawWheel();
  debug("Subscriber entries cleared");
}

function addSubscriberUnits(name, units, source = "unknown") {
  const safeUnits = Math.max(
    0,
    Math.floor(Number(units) || 0)
  );

  if (!safeUnits) return 0;

  let addedCount = 0;

  for (let index = 0; index < safeUnits; index += 1) {
    if (!addSubscriber(name, source)) break;
    addedCount += 1;
  }

  return addedCount;
}

function addSubscriber(name, source = "unknown") {
  if (!collecting || manualMode || spinning) return false;

  const cleanName = String(name || "").trim();
  const key = cleanName.toLowerCase();

  if (!cleanName) return false;

  const currentCount = subscriberEntryCounts.get(key) || 0;

  if (
    maxEntriesPerPerson > 0 &&
    currentCount >= maxEntriesPerPerson
  ) {
    debug("Subscriber entry cap reached", {
      name: cleanName,
      source,
      currentCount,
      maxEntriesPerPerson
    });

    return false;
  }

  subscriberEntries.push(cleanName);
  subscriberEntryCounts.set(key, currentCount + 1);
  drawWheel();

  debug("Subscriber entered", {
    name: cleanName,
    source,
    personEntries: currentCount + 1,
    maxEntriesPerPerson,
    totalEntries: subscriberEntries.length,
    uniquePeople: subscriberEntryCounts.size
  });

  return true;
}

function getDeep(data, paths) {
  for (const path of paths) {
    let value = data;

    for (const part of path.split(".")) {
      value = value?.[part];
    }

    if (value !== undefined && value !== null && value !== "") {
      return value;
    }
  }

  return "";
}

function normalizeSubscriptionEvent(eventName, data) {
  const name = String(eventName || "").toLowerCase();
  const serialized = JSON.stringify(data || {}).toLowerCase();

  const isSubRelated =
    name.includes("sub") ||
    serialized.includes('"subscription"') ||
    serialized.includes('"resub"') ||
    serialized.includes('"prime"');

  if (!isSubRelated) return null;

  const isGiftEvent =
    name.includes("gift") ||
    serialized.includes('"gifted"') ||
    serialized.includes('"gift_count"') ||
    serialized.includes('"total_gifts"');

  const isGiftRecipient =
    data?.is_gift === true ||
    data?.event?.is_gift === true ||
    data?.subscription?.is_gift === true ||
    name.includes("recipient") ||
    name.includes("gifted_sub_received");

  if (isGiftEvent) {
    const purchaser = getDeep(data, [
      "gifter_user_name",
      "gifter_name",
      "gifter.display_name",
      "gifter.username",
      "sender.display_name",
      "sender.username",
      "user.display_name",
      "user.username",
      "display_name",
      "username",
      "name",
      "event.user_name",
      "event.user_login"
    ]);

    const isAnonymous =
      data?.is_anonymous === true ||
      data?.event?.is_anonymous === true ||
      String(purchaser).toLowerCase().includes("anonymous");

    if (purchaser && !isAnonymous) {
      return {
        entrant: purchaser,
        source: "gift-purchaser"
      };
    }

    return null;
  }

  if (isGiftRecipient) return null;

  const subscriber = getDeep(data, [
    "subscriber.display_name",
    "subscriber.username",
    "sender.display_name",
    "sender.username",
    "user.display_name",
    "user.username",
    "display_name",
    "username",
    "name",
    "event.user_name",
    "event.user_login",
    "subscription.user_name"
  ]);

  return subscriber
    ? {
      entrant: subscriber,
      source: name.includes("resub") ? "resub" : "paid-or-prime-sub"
    }
    : null;
}



function activeConnectionLabel() {
  return useRemoteConnection ? "REMOTE" : "LOCAL";
}

function resolvedStreamerBotSocketUrl() {
  return useRemoteConnection
    ? remoteWebSocketUrl
    : localWebSocketUrl;
}

function bytesToBase64(bytes) {
  let binary = "";

  for (let index = 0; index < bytes.length; index += 1) {
    binary += String.fromCharCode(bytes[index]);
  }

  return btoa(binary);
}

async function sha256Base64(value) {
  if (!globalThis.crypto?.subtle) {
    throw new Error("Web Crypto API is unavailable");
  }

  const encoded = new TextEncoder().encode(String(value));
  const digest = await globalThis.crypto.subtle.digest("SHA-256", encoded);

  return bytesToBase64(new Uint8Array(digest));
}

async function buildStreamerBotAuthentication(password, salt, challenge) {
  const secret = await sha256Base64(
    String(password) + String(salt)
  );

  return sha256Base64(
    secret + String(challenge)
  );
}

function subscribeToStreamerBot() {
  if (
    !streamerBotSocket ||
    streamerBotSocket.readyState !== WebSocket.OPEN ||
    streamerBotSubscribed
  ) {
    return;
  }

  streamerBotSubscribed = true;

  streamerBotSocket.send(JSON.stringify({
    request: "Subscribe",
    id: "pogly-wheel-subscribe",
    events: {
      Twitch: ["Sub", "ReSub", "GiftSub", "GiftBomb"],
      Custom: ["Event"]
    }
  }));

  streamerBotSocket.send(JSON.stringify({
    request: "GetInfo",
    id: "pogly-wheel-info"
  }));
}

async function handleStreamerBotHello(message) {
  const authentication = message?.authentication;

  if (!authentication) {
    streamerBotAuthenticated = true;
    subscribeToStreamerBot();
    return;
  }

  if (!streamerBotPassword) {
    streamerBotAuthenticated = false;
    setStreamerBotStatus(
      `STREAMER.BOT: PASSWORD REQUIRED (${activeConnectionLabel()})`,
      "offline"
    );
    debug("Streamer.bot authentication is enabled, but no password was provided");
    return;
  }

  try {
    setStreamerBotStatus(
      `STREAMER.BOT: AUTHENTICATING (${activeConnectionLabel()})`
    );

    const authenticationString = await buildStreamerBotAuthentication(
      streamerBotPassword,
      authentication.salt,
      authentication.challenge
    );

    streamerBotSocket.send(JSON.stringify({
      request: "Authenticate",
      id: "pogly-wheel-authenticate",
      authentication: authenticationString
    }));
  } catch (error) {
    streamerBotAuthenticated = false;
    setStreamerBotStatus(
      `STREAMER.BOT: AUTH FAILED (${activeConnectionLabel()})`,
      "offline"
    );
    debug("Could not create Streamer.bot authentication response", error);
  }
}

function reconnectStreamerBot() {
  if (streamerBotReconnectTimer) {
    clearTimeout(streamerBotReconnectTimer);
    streamerBotReconnectTimer = 0;
  }

  if (streamerBotSocket) {
    try {
      streamerBotSocket.close();
    } catch (_) { }
  }

  streamerBotSocket = null;
  streamerBotAuthenticated = false;
  streamerBotSubscribed = false;
  connectToStreamerBot();
}

function hideStreamerBotStatus() {
  if (!streamerBotStatusEl) return;

  if (streamerBotStatusHideTimer) {
    clearTimeout(streamerBotStatusHideTimer);
    streamerBotStatusHideTimer = 0;
  }

  streamerBotStatusEl.classList.remove("visible");
}

function setStreamerBotStatus(text, state = "", autoHideMs = 0) {
  if (!streamerBotStatusEl) return;

  if (streamerBotStatusHideTimer) {
    clearTimeout(streamerBotStatusHideTimer);
    streamerBotStatusHideTimer = 0;
  }

  streamerBotStatusEl.textContent = text;
  streamerBotStatusEl.classList.remove("connected", "offline");
  if (state) streamerBotStatusEl.classList.add(state);
  streamerBotStatusEl.classList.add("visible");

  if (autoHideMs > 0) {
    streamerBotStatusHideTimer = setTimeout(
      hideStreamerBotStatus,
      autoHideMs
    );
  }
}
function streamerBotName(data) {
  const values = [data?.user?.display, data?.user?.displayName, data?.user?.name, data?.user?.login, data?.display, data?.displayName, data?.name, data?.login, data?.gifter?.display, data?.gifter?.displayName, data?.gifter?.name, data?.gifter?.login];
  return String(values.find(v => v !== undefined && v !== null && v !== "") || "").trim();
}
function handleWheelCommand(payload) {
  if (!payload || typeof payload !== "object") return;

  const command =
    payload.wheelCommand ||
    payload.command ||
    payload.type ||
    "";

  if (command === "addSubscriber") {
    const name =
      payload.name ||
      payload.username ||
      payload.user?.display ||
      payload.user?.name ||
      "Test Subscriber";

    /*
     * In manual mode, the same Streamer.bot test command now counts
     * toward Community Subs instead of trying to add a subscriber
     * entry to the subscriber wheel.
     */
    if (manualMode && autoSpinFromSubs) {
      const units = Math.max(
        1,
        Math.floor(
          Number(
            payload.count ??
            payload.amount ??
            payload.quantity ??
            payload.giftCount ??
            1
          ) || 1
        )
      );

      const added = addCommunitySubUnits(
        units,
        payload.source || "streamerbot-test"
      );

      if (added) {
        setStreamerBotStatus(
          `TEST RECEIVED: +${units} SUB${units === 1 ? "" : "S"}`,
          "connected",
          1800
        );
      }

      return;
    }

    if (name) {
      const added = addSubscriber(
        name,
        payload.source || "streamerbot-test"
      );

      if (added) {
        setStreamerBotStatus(
          `TEST RECEIVED: ${name}`,
          "connected",
          1800
        );
      } else if (!collecting) {
        setStreamerBotStatus(
          "ADD IGNORED: NOT COLLECTING",
          "connected",
          1800
        );
      }
    }

    return;
  }

  if (command === "addCommunitySubs") {
    const units = Math.max(
      1,
      Math.floor(
        Number(
          payload.count ??
          payload.amount ??
          payload.quantity ??
          payload.giftCount ??
          1
        ) || 1
      )
    );

    if (!manualMode) {
      setStreamerBotStatus(
        "TEST IGNORED: NOT MANUAL MODE",
        "connected",
        1800
      );
      return;
    }

    if (!autoSpinFromSubs) {
      setStreamerBotStatus(
        "TEST IGNORED: AUTO SPIN OFF",
        "connected",
        1800
      );
      return;
    }

    addCommunitySubUnits(
      units,
      payload.source || "streamerbot-community-test"
    );

    setStreamerBotStatus(
      `TEST RECEIVED: +${units} SUB${units === 1 ? "" : "S"}`,
      "connected",
      1800
    );

    return;
  }

  if (command === "startCollection") {
    startCollection();
    return;
  }

  if (command === "stopCollection") {
    stopCollection(true);
    return;
  }

  if (command === "spinWheel") {
    spinWheel();
    return;
  }

  if (
    command === "masterStop" ||
    command === "masterStopSpin" ||
    command === "clearSpinQueue"
  ) {
    masterStopSpinAndClearQueue();
    return;
  }

  if (command === "clearSubscribers") {
    clearSubscribers();
  }
}

function handleStreamerBotEvent(message) {
  const source = String(message?.event?.source || "");
  const type = String(message?.event?.type || "");
  const data = message?.data || {};

  if (source === "Custom" && type === "Event") {
    const eventName = String(
      data?.eventName ||
      data?.name ||
      data?.event ||
      ""
    ).trim();

    debug("Streamer.bot Custom.Event received", { eventName, data });

    function showCommandStatus(text) {
      setStreamerBotStatus(text, "connected", 1800);
    }

    if (eventName.startsWith("wheel:addGiftBomb:")) {
      const parts = eventName
        .slice("wheel:addGiftBomb:".length)
        .split(":");

      const rawCount = String(parts.shift() || "").trim();
      const gifterName = parts.join(":").trim() || "Gift Gifter";
      const units = Math.max(
        1,
        Math.floor(Number(rawCount) || 1)
      );

      if (manualMode && autoSpinFromSubs) {
        const added = registerManualGiftBomb(
          units,
          gifterName
        );

        if (manualGiftBombOnly) {
          const spins = Math.floor(
            units / manualGiftBombRequired
          );

          showCommandStatus(
            added
              ? `GIFT BOMB: ${spins} SPIN${spins === 1 ? "" : "S"}`
              : `GIFT BOMB BELOW ${manualGiftBombRequired}`
          );
        } else {
          showCommandStatus(
            added
              ? `GIFT BOMB: +${units} SUBS`
              : "GIFT BOMB IGNORED"
          );
        }

        return;
      }

      if (!manualMode) {
        const key = normalizeEventUser(gifterName);

        if (subGiftBombOnly) {
          const earnedEntries = Math.floor(
            units / subGiftBombRequired
          );

          recentGiftBombs.set(key, Date.now());

          setTimeout(() => {
            const timestamp = recentGiftBombs.get(key) || 0;
            if (Date.now() - timestamp >= GIFT_BOMB_DEDUPE_MS) {
              recentGiftBombs.delete(key);
            }
          }, GIFT_BOMB_DEDUPE_MS + 100);

          if (earnedEntries <= 0) {
            showCommandStatus(
              `GIFT BOMB BELOW ${subGiftBombRequired}`
            );
            return;
          }

          const addedCount = addSubscriberUnits(
            gifterName,
            earnedEntries,
            "gift-bomb-threshold-entry"
          );

          showCommandStatus(
            `GIFT BOMB: ${addedCount} ENTR${addedCount === 1 ? "Y" : "IES"}`
          );
          return;
        }

        const pairedNameEvent =
          recentSubscriberNameEvents.get(key);

        let alreadyAddedByPairedEvent = 0;

        if (
          pairedNameEvent &&
          Date.now() - pairedNameEvent.at <= GIFT_BOMB_DEDUPE_MS
        ) {
          alreadyAddedByPairedEvent =
            Math.max(0, pairedNameEvent.count || 0);

          recentSubscriberNameEvents.delete(key);
        }

        const remainingUnits = Math.max(
          0,
          units - alreadyAddedByPairedEvent
        );

        const addedCount = addSubscriberUnits(
          gifterName,
          remainingUnits,
          "gift-bomb-purchaser"
        );

        recentGiftBombs.set(key, Date.now());

        setTimeout(() => {
          const timestamp = recentGiftBombs.get(key) || 0;

          if (Date.now() - timestamp >= GIFT_BOMB_DEDUPE_MS) {
            recentGiftBombs.delete(key);
          }
        }, GIFT_BOMB_DEDUPE_MS + 100);

        showCommandStatus(
          `GIFT BOMB: ${addedCount + alreadyAddedByPairedEvent} ENTRIES`
        );

        return;
      }

      showCommandStatus(
        "GIFT BOMB IGNORED: AUTO SPIN OFF"
      );

      return;
    }

    if (eventName.startsWith("wheel:addCommunitySubs:")) {
      const rawCount = eventName
        .slice("wheel:addCommunitySubs:".length)
        .trim();

      const units = Math.max(
        1,
        Math.floor(Number(rawCount) || 1)
      );

      if (!manualMode) {
        showCommandStatus(
          "COMMUNITY SUBS IGNORED: NOT MANUAL MODE"
        );
        return;
      }

      if (!autoSpinFromSubs) {
        showCommandStatus(
          "COMMUNITY SUBS IGNORED: AUTO SPIN OFF"
        );
        return;
      }

      const added = addCommunitySubUnits(
        units,
        "streamerbot-legacy-community-event"
      );

      if (added) {
        showCommandStatus(
          `COMMUNITY SUBS: +${units}`
        );
      } else {
        showCommandStatus(
          "COMMUNITY SUBS IGNORED"
        );
      }

      return;
    }

    if (eventName.startsWith("wheel:addSubscriber:")) {
      const name = eventName
        .slice("wheel:addSubscriber:".length)
        .trim();

      /*
       * The existing Streamer.bot test action uses this Custom.Event.
       * In manual + auto-spin mode, treat it as +1 community sub.
       * In subscriber mode, preserve the original add-subscriber behavior.
       */
      if (manualMode && autoSpinFromSubs) {
        const queued = queueManualSingleSub(
          name || "Subscriber",
          "streamerbot-custom-sub"
        );

        showCommandStatus(
          queued
            ? "SUB RECEIVED: +1"
            : "SUB IGNORED"
        );

        return;
      }

      if (name) {
        const key = normalizeEventUser(name);

        if (!manualMode && subGiftBombOnly) {
          showCommandStatus(
            "SUB IGNORED: GIFT BOMB ONLY"
          );
          return;
        }

        const recentBombAt = recentGiftBombs.get(key) || 0;

        /*
         * When the counted Gift Bomb event arrived first, ignore the
         * paired one-entry name event so the bomb is not over-counted.
         */
        if (
          !manualMode &&
          Date.now() - recentBombAt <= GIFT_BOMB_DEDUPE_MS
        ) {
          showCommandStatus(
            "PAIRED GIFT BOMB NAME EVENT IGNORED"
          );
          return;
        }

        const added = addSubscriber(
          name,
          "streamerbot-custom-event"
        );

        if (added && !manualMode) {
          recentSubscriberNameEvents.set(key, {
            at: Date.now(),
            count: 1
          });

          setTimeout(() => {
            const record = recentSubscriberNameEvents.get(key);

            if (
              record &&
              Date.now() - record.at >= GIFT_BOMB_DEDUPE_MS
            ) {
              recentSubscriberNameEvents.delete(key);
            }
          }, GIFT_BOMB_DEDUPE_MS + 100);
        }

        if (added) {
          showCommandStatus(`ADDED: ${name}`);
        } else if (!collecting) {
          showCommandStatus("ADD IGNORED: NOT COLLECTING");
        } else if (manualMode) {
          showCommandStatus("ADD IGNORED: MANUAL MODE");
        } else {
          showCommandStatus("ADD IGNORED: ENTRY CAP");
        }
      }

      return;
    }

    if (eventName === "wheel:startCollection") {
      startCollection();

      if (collecting) {
        showCommandStatus("COLLECTION STARTED");
      } else if (manualMode) {
        showCommandStatus("START IGNORED: MANUAL MODE");
      }

      return;
    }

    if (eventName === "wheel:stopCollection") {
      stopCollection(true);
      showCommandStatus("COLLECTION STOPPED");
      return;
    }

    if (eventName === "wheel:spin") {
      const hadEntries = currentEntries().length > 0;

      spinWheel();

      showCommandStatus(
        hadEntries
          ? "SPIN TRIGGERED"
          : "SPIN IGNORED: NO ENTRIES"
      );

      return;
    }

    if (eventName === "wheel:masterStop") {
      masterStopSpinAndClearQueue();
      showCommandStatus("MASTER STOP ACTIVATED");
      return;
    }

    if (eventName === "wheel:clear") {
      clearSubscribers();
      showCommandStatus("SUBSCRIBERS CLEARED");
      return;
    }

    if (eventName === "wheel:closeResult") {
      hideResult();
      showCommandStatus("RESULT CLOSED");
      return;
    }

    return;
  }

  if (source !== "Twitch") return;
  debug("Streamer.bot event received", { source, type, data });

  if (!manualMode && subGiftBombOnly) {
    debug("Native Twitch subscription event ignored in sub gift-bomb-only mode", {
      type,
      data
    });
    return;
  }

  /*
   * Manual auto-spin is driven only by the deliberate Custom Events.
   * This prevents native Twitch events and Streamer.bot actions from
   * counting the same subscription twice.
   */
  if (manualMode && autoSpinFromSubs) {
    debug("Native Twitch event ignored in manual auto-spin mode", {
      type,
      data
    });
    return;
  }
  if (type === "Sub") {
    if (manualMode) {
      addCommunitySubUnits(
        1,
        data?.isPrime === true
          ? "prime-sub"
          : "paid-sub"
      );
      return;
    }

    const name = streamerBotName(data);
    if (name) {
      addSubscriber(
        name,
        data?.isPrime === true
          ? "prime-sub"
          : "paid-sub"
      );
    }

    return;
  }

  if (type === "ReSub") {
    if (data?.isGift === true || data?.gifted === true) return;

    if (manualMode) {
      addCommunitySubUnits(
        1,
        data?.isPrime === true
          ? "prime-resub"
          : "resub"
      );
      return;
    }

    const name = streamerBotName(data);
    if (name) {
      addSubscriber(
        name,
        data?.isPrime === true
          ? "prime-resub"
          : "resub"
      );
    }

    return;
  }

  /*
   * Count each GiftSub event as one gifted subscription.
   * Gift bombs generate individual GiftSub events, so GiftBomb itself
   * is intentionally not added again. This prevents double counting.
   */
  if (type === "GiftSub") {
    if (manualMode) {
      addCommunitySubUnits(1, "gift-sub");
    }

    return;
  }

  if (type === "GiftBomb") {
    if (manualMode) {
      debug(
        "GiftBomb received; waiting for its individual GiftSub events",
        data
      );
      return;
    }

    const anonymous =
      data?.isAnonymous === true ||
      data?.anonymous === true ||
      data?.gifterIsAnonymous === true;

    if (anonymous) return;

    const name = streamerBotName({
      ...data,
      user: data?.gifter || data?.user
    });

    if (name) addSubscriber(name, "gift-purchaser");
  }
}
function scheduleStreamerBotReconnect() {
  if (streamerBotReconnectTimer) return;

  streamerBotReconnectTimer = setTimeout(() => {
    streamerBotReconnectTimer = 0;
    connectToStreamerBot();
  }, 3000);
}

function connectToStreamerBot() {
  if (streamerBotReconnectTimer) {
    clearTimeout(streamerBotReconnectTimer);
    streamerBotReconnectTimer = 0;
  }

  if (
    streamerBotSocket &&
    (
      streamerBotSocket.readyState === WebSocket.OPEN ||
      streamerBotSocket.readyState === WebSocket.CONNECTING
    )
  ) {
    return;
  }

  const socketUrl = resolvedStreamerBotSocketUrl();
  const connectionLabel = activeConnectionLabel();

  if (!socketUrl) {
    setStreamerBotStatus(
      `STREAMER.BOT: ${connectionLabel} URL REQUIRED`,
      "offline"
    );
    debug("No Streamer.bot WebSocket URL configured", {
      useRemoteConnection
    });
    return;
  }

  streamerBotAuthenticated = false;
  streamerBotSubscribed = false;

  setStreamerBotStatus(
    `STREAMER.BOT: CONNECTING (${connectionLabel})`
  );

  try {
    streamerBotSocket = new WebSocket(socketUrl);
  } catch (error) {
    debug("Streamer.bot connection creation failed", error);
    setStreamerBotStatus(
      `STREAMER.BOT: OFFLINE (${connectionLabel})`,
      "offline"
    );
    scheduleStreamerBotReconnect();
    return;
  }

  streamerBotSocket.addEventListener("open", () => {
    setStreamerBotStatus(
      `STREAMER.BOT: CONNECTED (${connectionLabel}) — WAITING FOR HELLO`
    );

    debug("Connected to Streamer.bot", {
      connectionMode: connectionLabel,
      socketUrl
    });
  });

  streamerBotSocket.addEventListener("message", async event => {
    let message;

    try {
      message = JSON.parse(event.data);
    } catch (error) {
      debug("Streamer.bot sent non-JSON data", event.data);
      return;
    }

    if (message?.request === "Hello") {
      await handleStreamerBotHello(message);
      return;
    }

    if (message?.id === "pogly-wheel-authenticate") {
      if (message?.status === "ok") {
        streamerBotAuthenticated = true;

        setStreamerBotStatus(
          `STREAMER.BOT: AUTHENTICATED (${activeConnectionLabel()})`,
          "connected",
          1800
        );

        subscribeToStreamerBot();
      } else {
        streamerBotAuthenticated = false;
        streamerBotSubscribed = false;

        setStreamerBotStatus(
          `STREAMER.BOT: WRONG PASSWORD (${activeConnectionLabel()})`,
          "offline"
        );

        debug("Streamer.bot authentication failed", message);
      }

      return;
    }

    if (message?.id === "pogly-wheel-info" && message?.status === "ok") {
      const version = message?.info?.version
        ? ` v${message.info.version}`
        : "";

      setStreamerBotStatus(
        `STREAMER.BOT${version}: CONNECTED (${activeConnectionLabel()})`,
        "connected",
        2200
      );
    }

    if (message?.event) {
      if (
        message.event.source === "General" &&
        message.event.type === "Custom"
      ) {
        let customData =
          message?.data?.data ??
          message?.data;

        if (typeof customData === "string") {
          try {
            customData = JSON.parse(customData);
          } catch (error) {
            debug("Could not parse General.Custom data", customData);
          }
        }

        handleWheelCommand(customData);
      } else {
        handleStreamerBotEvent(message);
      }
    } else {
      handleWheelCommand(message);
    }
  });

  streamerBotSocket.addEventListener("close", () => {
    streamerBotAuthenticated = false;
    streamerBotSubscribed = false;

    setStreamerBotStatus(
      `STREAMER.BOT: OFFLINE (${activeConnectionLabel()})`,
      "offline"
    );

    scheduleStreamerBotReconnect();
  });

  streamerBotSocket.addEventListener("error", error => {
    debug("Streamer.bot socket error", error);
  });
}

document.addEventListener("widgetEvent", event => {
  const eventName =
    event.detail?.event_name ||
    event.detail?.eventName ||
    event.detail?.type ||
    "";

  const data =
    event.detail?.data ||
    event.detail?.event ||
    event.detail ||
    {};

  debug("Raw Pogly widget event", {
    eventName,
    data
  });

  if (!manualMode && subGiftBombOnly) {
    debug("Pogly subscription event ignored in sub gift-bomb-only mode", {
      eventName,
      data
    });
    return;
  }

  const normalized = normalizeSubscriptionEvent(eventName, data);

  if (normalized) {
    addSubscriber(normalized.entrant, normalized.source);
  }
});

function startIdleSpin() {
  if (idleSpinFrame) return;

  idleSpinLastTime = performance.now();

  function animateIdle(now) {
    const deltaSeconds = Math.min(
      0.1,
      Math.max(0, (now - idleSpinLastTime) / 1000)
    );

    idleSpinLastTime = now;

    if (
      idleSpinEnabled &&
      !spinning
    ) {
      const rotationsPerSecond =
        Math.max(0, idleSpinRotationsPerMinute) / 60;

      rotation += rotationsPerSecond * TAU * deltaSeconds;

      /*
       * Prevent the stored angle from growing forever during
       * long streams while preserving the exact visual rotation.
       */
      if (rotation > TAU * 1000) {
        rotation %= TAU;
      }

      drawWheel();
    }

    idleSpinFrame = requestAnimationFrame(animateIdle);
  }

  idleSpinFrame = requestAnimationFrame(animateIdle);
}

function stopIdleSpin() {
  cancelAnimationFrame(idleSpinFrame);
  idleSpinFrame = 0;
  idleSpinLastTime = 0;
}

function easeInOutQuint(value) {
  return value < .5
    ? 16 * value ** 5
    : 1 - Math.pow(-2 * value + 2, 5) / 2;
}

function masterStopSpinAndClearQueue() {
  /*
   * Invalidate the current spin and cancel its next animation frame.
   * Any already-running animation callback will also see the changed
   * generation value and exit without selecting a winner.
   */
  spinGeneration += 1;

  if (activeSpinFrame) {
    cancelAnimationFrame(activeSpinFrame);
    activeSpinFrame = 0;
  }

  spinning = false;

  /*
   * Clear every queued automatic spin and delayed community-sub event.
   * The visible community progress (for example 3 / 5) is preserved.
   */
  pendingCommunitySpins = 0;
  clearCommunitySpinTimer();
  clearCommunityGoalFlash();

  pendingManualSubTimers.forEach(timer => {
    clearTimeout(timer);
  });
  pendingManualSubTimers.clear();

  /*
   * Close any winner card and stop confetti.
   */
  if (resultTimer) {
    clearTimeout(resultTimer);
    resultTimer = 0;
  }

  resultOverlay.classList.add("hidden");
  stopConfetti();

  drawWheel();
  updateTimerDisplay();

  setStreamerBotStatus(
    "MASTER STOP: SPIN + QUEUE CLEARED",
    "connected",
    2400
  );

  debug("Master stop activated", {
    communitySubProgress,
    pendingCommunitySpins
  });
}

function spinWheel() {
  const entries = currentEntries();

  if (spinning || entries.length === 0) return;

  spinning = true;
  hideResult();

  const thisSpinGeneration = ++spinGeneration;
  const winnerIndex = Math.floor(Math.random() * entries.length);
  const sliceAngle = TAU / entries.length;

  /*
   * The pointer sits on the right side at angle zero.
   * Slice centers begin at index * sliceAngle because drawing
   * offsets every slice by half a slice.
   */
  const winningCenter = winnerIndex * sliceAngle;
  const normalizedRotation = ((rotation % TAU) + TAU) % TAU;
  const desiredNormalized = ((-winningCenter % TAU) + TAU) % TAU;
  const correction =
    ((desiredNormalized - normalizedRotation) % TAU + TAU) % TAU;

  const totalRotation =
    minimumRotations * TAU +
    correction;

  const startRotation = rotation;
  const durationMs = Math.max(3, spinDurationSeconds) * 1000;
  const startTime = performance.now();

  function animate(now) {
    if (thisSpinGeneration !== spinGeneration) {
      activeSpinFrame = 0;
      return;
    }

    const progress = Math.min(1, (now - startTime) / durationMs);
    const eased = easeInOutQuint(progress);

    rotation = startRotation + totalRotation * eased;
    drawWheel();

    if (progress < 1) {
      activeSpinFrame = requestAnimationFrame(animate);
      return;
    }

    activeSpinFrame = 0;
    rotation = startRotation + totalRotation;
    drawWheel();

    if (thisSpinGeneration !== spinGeneration) {
      spinning = false;
      return;
    }

    const winner = entries[winnerIndex];
    spinning = false;
    showResult(winner);

    /*
     * Subscriber-mode prize drawing:
     * remove every slice belonging to the winner so the same person
     * cannot win 1st, 2nd, and 3rd place.
     *
     * The original Remove Winner After Spin option is preserved:
     * it still removes only one entry/slice.
     */
    if (!manualMode && removeSubWinnerAfterSpin) {
      removeAllSubscriberEntries(winner);
    } else if (removeWinnerAfterSpin) {
      removeWinner(winner);
    }
  }

  activeSpinFrame = requestAnimationFrame(animate);
}

function removeAllSubscriberEntries(winner) {
  if (manualMode) return 0;

  const key = String(winner || "").trim().toLowerCase();
  if (!key) return 0;

  const beforeCount = subscriberEntries.length;

  subscriberEntries = subscriberEntries.filter(
    item => String(item || "").trim().toLowerCase() !== key
  );

  const removedCount = beforeCount - subscriberEntries.length;

  subscriberEntryCounts.delete(key);
  drawWheel();

  debug("Subscriber winner fully removed", {
    winner,
    removedCount,
    remainingEntries: subscriberEntries.length,
    remainingPeople: subscriberEntryCounts.size
  });

  return removedCount;
}

function removeWinner(winner) {
  const key = String(winner || "").trim().toLowerCase();

  if (manualMode) {
    const index = manualEntries.findIndex(
      item => String(item || "").trim().toLowerCase() === key
    );

    if (index >= 0) manualEntries[index] = "";
  } else {
    const index = subscriberEntries.findIndex(
      item => String(item || "").trim().toLowerCase() === key
    );

    if (index >= 0) {
      subscriberEntries.splice(index, 1);

      const remainingCount =
        (subscriberEntryCounts.get(key) || 1) - 1;

      if (remainingCount > 0) {
        subscriberEntryCounts.set(key, remainingCount);
      } else {
        subscriberEntryCounts.delete(key);
      }
    }
  }

  drawWheel();
}

function showResult(winner) {
  resultHeaderEl.textContent = resultHeader;
  resultWinnerEl.textContent = winner;
  resultOverlay.classList.remove("hidden");

  if (resultSoundUrl) {
    const audio = new Audio(resultSoundUrl);
    audio.volume = normalizeVolume(resultSoundVolume);
    audio.play().catch(() => { });
  }

  if (confettiEnabled) {
    launchConfetti();
  }

  if (resultTimer) clearTimeout(resultTimer);

  if (resultDisplaySeconds > 0) {
    resultTimer = setTimeout(
      hideResult,
      resultDisplaySeconds * 1000
    );
  }
}

function hideResult() {
  if (resultTimer) clearTimeout(resultTimer);
  resultTimer = 0;
  resultOverlay.classList.add("hidden");
  stopConfetti();

  if (pendingCommunitySpins > 0) {
    clearCommunitySpinTimer();

    communitySpinTimer = setTimeout(() => {
      communitySpinTimer = 0;
      processCommunitySpinQueue();
    }, 350);
  }
}

function launchConfetti() {
  resizeConfettiCanvas();
  confettiPieces = [];

  const colors = palette.length
    ? palette
    : ["#ff2d95", "#6a38ff", "#00b8ff", "#00d98b", "#ff8a00"];

  for (let index = 0; index < 160; index++) {
    confettiPieces.push({
      x: confettiCanvas.width / 2,
      y: confettiCanvas.height * .42,
      vx: (Math.random() - .5) * 15,
      vy: -5 - Math.random() * 12,
      gravity: .22 + Math.random() * .16,
      rotation: Math.random() * TAU,
      rotationSpeed: (Math.random() - .5) * .35,
      width: 7 + Math.random() * 9,
      height: 4 + Math.random() * 6,
      color: colors[index % colors.length],
      life: 0,
      maxLife: 150 + Math.random() * 80
    });
  }

  cancelAnimationFrame(confettiFrame);

  function animate() {
    confettiCtx.clearRect(
      0,
      0,
      confettiCanvas.width,
      confettiCanvas.height
    );

    confettiPieces.forEach(piece => {
      piece.x += piece.vx;
      piece.y += piece.vy;
      piece.vy += piece.gravity;
      piece.vx *= .992;
      piece.rotation += piece.rotationSpeed;
      piece.life++;

      const opacity = Math.max(
        0,
        1 - piece.life / piece.maxLife
      );

      confettiCtx.save();
      confettiCtx.globalAlpha = opacity;
      confettiCtx.translate(piece.x, piece.y);
      confettiCtx.rotate(piece.rotation);
      confettiCtx.fillStyle = piece.color;
      confettiCtx.fillRect(
        -piece.width / 2,
        -piece.height / 2,
        piece.width,
        piece.height
      );
      confettiCtx.restore();
    });

    confettiPieces = confettiPieces.filter(
      piece =>
        piece.life < piece.maxLife &&
        piece.y < confettiCanvas.height + 50
    );

    if (confettiPieces.length) {
      confettiFrame = requestAnimationFrame(animate);
    } else {
      stopConfetti();
    }
  }

  confettiFrame = requestAnimationFrame(animate);
}

function stopConfetti() {
  cancelAnimationFrame(confettiFrame);
  confettiFrame = 0;
  confettiPieces = [];
  confettiCtx.clearRect(
    0,
    0,
    confettiCanvas.width,
    confettiCanvas.height
  );
}

function resizeConfettiCanvas() {
  confettiCanvas.width =
    Math.max(1, confettiCanvas.clientWidth);
  confettiCanvas.height =
    Math.max(1, confettiCanvas.clientHeight);
}

function refreshPalette() {
  palette = [
    "{color_1}",
    "{color_2}",
    "{color_3}",
    "{color_4}",
    "{color_5}"
  ].filter(isUsableColor);

  drawWheel();
}

function onLiveVariableUpdate(name, value) {
  if (name === "manual_mode") {
    manualMode = parseToggle(value);

    if (!manualMode) {
      pendingManualSubTimers.forEach(timer => clearTimeout(timer));
      pendingManualSubTimers.clear();
      clearCommunityGoalFlash();
    }

    stopCollection(false);
    updateTimerDisplay();
    drawWheel();

    if (manualMode) {
      processCommunitySpinQueue();
    }
  }
  else if (name === "manual_header_text") {
    manualHeaderText = value;
    if (manualMode) updateTimerDisplay();
  }
  else if (name === "auto_spin_from_subs") {
    autoSpinFromSubs = parseToggle(value);

    if (!autoSpinFromSubs) {
      pendingManualSubTimers.forEach(timer => clearTimeout(timer));
      pendingManualSubTimers.clear();
      clearCommunityGoalFlash();
    }

    updateTimerDisplay();

    if (autoSpinFromSubs) {
      processCommunitySpinQueue();
    }
  }
  else if (name === "manual_gift_bomb_only") {
    manualGiftBombOnly = parseToggle(value);

    pendingManualSubTimers.forEach(timer => clearTimeout(timer));
    pendingManualSubTimers.clear();
    clearCommunityGoalFlash();
    updateTimerDisplay();
  }
  else if (name === "manual_gift_bomb_required") {
    manualGiftBombRequired = Math.max(
      1,
      parseInt(value, 10) || 10
    );
    updateTimerDisplay();
  }
  else if (name === "sub_gift_bomb_only") {
    subGiftBombOnly = parseToggle(value);
    recentSubscriberNameEvents.clear();
    recentGiftBombs.clear();
    updateTimerDisplay();
    drawWheel();
  }
  else if (name === "sub_gift_bomb_required") {
    subGiftBombRequired = Math.max(
      1,
      parseInt(value, 10) || 10
    );
    updateTimerDisplay();
    updateEntryCount();
  }
  else if (name === "community_subs_per_spin") {
    communitySubsPerSpin = Math.max(
      1,
      parseInt(value, 10) || 5
    );

    /*
     * Preserve accumulated subs when the threshold changes.
     * A lower threshold may immediately create one or more spins.
     */
    const earnedSpins = Math.floor(
      communitySubProgress / communitySubsPerSpin
    );

    if (earnedSpins > 0) {
      pendingCommunitySpins += earnedSpins;
      communitySubProgress %=
        communitySubsPerSpin;
    }

    updateTimerDisplay();
    processCommunitySpinQueue();
  }
  else if (name === "start_collecting_subs") {
    startCollection();
  }
  else if (name === "stop_collecting_subs") {
    stopCollection(true);
  }
  else if (name === "clear_subscriber_list") {
    clearSubscribers();
  }
  else if (name === "spin_wheel") {
    spinWheel();
  }
  else if (name === "master_stop_spin_clear_queue") {
    masterStopSpinAndClearQueue();
  }
  else if (name === "close_result") {
    hideResult();
  }
  else if (name === "collection_time_minutes") {
    collectionMinutes = parseFloat(value);
  }
  else if (name === "max_entries_per_person") {
    maxEntriesPerPerson =
      Math.max(0, parseInt(value, 10) || 0);
    updateEntryCount();
  }
  else if (name === "auto_stop_at_timer_end") {
    autoStopAtEnd = parseToggle(value);
  }
  else if (name === "auto_spin_at_timer_end") {
    autoSpinAtEnd = parseToggle(value);
  }
  else if (name === "remove_winner_after_spin") {
    removeWinnerAfterSpin = parseToggle(value);
  }
  else if (name === "remove_sub_winner_after_spin") {
    removeSubWinnerAfterSpin = parseToggle(value);
  }
  else if (name === "confetti_enabled") {
    confettiEnabled = parseToggle(value);
  }
  else if (name === "result_header") {
    resultHeader = value;
    resultHeaderEl.textContent = value;
  }
  else if (name === "result_display_duration") {
    resultDisplaySeconds = parseFloat(value);
  }
  else if (name === "result_sound_url") {
    resultSoundUrl = value;
  }
  else if (name === "result_sound_volume") {
    resultSoundVolume = parseFloat(value);
  }
  else if (name === "spin_duration_seconds") {
    spinDurationSeconds = parseFloat(value);
  }
  else if (name === "minimum_full_rotations") {
    minimumRotations = parseInt(value, 10);
  }
  else if (name === "idle_spin_enabled") {
    idleSpinEnabled = parseToggle(value);
  }
  else if (name === "idle_spin_rotations_per_minute") {
    idleSpinRotationsPerMinute = parseFloat(value);
  }
  else if (name === "widget_scale") {
    widgetScaleMultiplier = parseFloat(value);
    applyWidgetScale();
  }
  else if (name === "use_remote_connection") {
    useRemoteConnection = parseToggle(value);
    reconnectStreamerBot();
  }
  else if (name === "local_websocket_url") {
    localWebSocketUrl =
      String(value || "").trim() ||
      "ws://127.0.0.1:8080/";

    reconnectStreamerBot();
  }
  else if (name === "remote_websocket_url") {
    remoteWebSocketUrl = String(value || "").trim();
    reconnectStreamerBot();
  }
  else if (name === "streamerbot_password") {
    streamerBotPassword = String(value || "");
    reconnectStreamerBot();
  }
  else if (/^color_[1-5]$/.test(name)) {
    const index = Number(name.split("_")[1]) - 1;
    palette[index] = value;
    palette = palette.filter(isUsableColor);
    drawWheel();
  }
  else if (/^manual_entry_(?:[1-9]|1[0-5])$/.test(name)) {
    const index = Number(name.split("_").pop()) - 1;
    manualEntries[index] = value;
    if (manualMode) drawWheel();
  }
}

